import{_ as e,o as a,c as o,a3 as d}from"./chunks/framework.WFmvnizL.js";const u=JSON.parse('{"title":"配置指南","description":"哪吒监控 V2 配置指南入口：理解配置文件、环境变量与后台设置的关系，选择 Dashboard 和 Agent 配置，按场景部署并验证生效。","frontmatter":{"description":"哪吒监控 V2 配置指南入口：理解配置文件、环境变量与后台设置的关系，选择 Dashboard 和 Agent 配置，按场景部署并验证生效。","outline":"deep"},"headers":[],"relativePath":"configuration/index.md","filePath":"configuration/index.md","lastUpdated":1792850916000}'),r={name:"configuration/index.md"};function n(i,t,l,s,h,c){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="配置指南" tabindex="-1">配置指南 <a class="header-anchor" href="#配置指南" aria-label="Permalink to &quot;配置指南&quot;">​</a></h1><p>配置哪吒分为两部分：Dashboard 决定入口、鉴权和数据存储；Agent 决定连接方式、采集项目及远程操作能力。两者使用独立 YAML 文件，字段和环境变量规则不能互换。</p><h2 id="从哪里开始" tabindex="-1">从哪里开始 <a class="header-anchor" href="#从哪里开始" aria-label="Permalink to &quot;从哪里开始&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>阅读</th></tr></thead><tbody><tr><td>找到正在使用的文件，理解加载与持久化</td><td><a href="/configuration/environment.html">配置加载与环境变量</a></td></tr><tr><td>查询面板的全部配置项和默认值</td><td><a href="/configuration/dashboard.html">Dashboard 配置</a></td></tr><tr><td>查询节点的全部配置项和默认值</td><td><a href="/configuration/agent.html">Agent 配置</a></td></tr><tr><td>配置反向代理、内置 HTTPS、轻量采集或存储</td><td><a href="/configuration/examples.html">场景配置与验证</a></td></tr><tr><td>修改通知、告警、任务和分组</td><td><a href="/guide/settings.html">使用指南：设置</a>及相邻功能页</td></tr><tr><td>开发或部署自己的用户主题</td><td><a href="/developer/theme-development.html">主题开发</a></td></tr></tbody></table><h2 id="推荐工作流" tabindex="-1">推荐工作流 <a class="header-anchor" href="#推荐工作流" aria-label="Permalink to &quot;推荐工作流&quot;">​</a></h2><ol><li><strong>确认实际运行方式。</strong> 检查容器挂载、进程参数或服务定义。Dashboard 默认读 <code>data/config.yaml</code>；Agent 默认读其可执行文件旁的 <code>config.yml</code>。安装脚本可能指定其它位置。</li><li><strong>备份当前状态。</strong> 保存配置和服务定义；涉及存储变更时按<a href="/guide/q5.html">备份与恢复</a>处理数据库和 TSDB。不要在多人可读的位置保存密钥。</li><li><strong>只改一个配置来源。</strong> 后台支持的选项优先使用后台；文件配置不要与环境变量重复定义。改监听、TLS 或密钥前保留本机恢复入口。</li><li><strong>应用并读回。</strong> 后台设置通常立即生效；本地文件修改需要重启对应进程。Agent 远程配置存在延迟，提交成功不等于已重连。</li><li><strong>验证实际链路。</strong> 页面能打开、Agent 持续上报、历史可查询、预期功能可用且禁用项确实被拒绝，才算完成。</li></ol><h2 id="不要混淆这些配置" tabindex="-1">不要混淆这些配置 <a class="header-anchor" href="#不要混淆这些配置" aria-label="Permalink to &quot;不要混淆这些配置&quot;">​</a></h2><ul><li>Dashboard 的 <code>tls</code> 仅影响安装命令；真正的服务端 HTTPS 由 <code>https</code> 或反向代理提供。Agent 的 <code>tls</code> 则决定实际连接是否使用 TLS。</li><li><code>install_host</code> 是 Agent 入口，<code>dashboard_host</code> 是面板公网访问及 OAuth2 回调 Host，<code>listen_host</code> 是本地绑定地址。</li><li>用户连接密钥用于 Agent 注册，不是 REST/MCP 的 PAT，也不是浏览器 JWT。</li><li><code>online_stats_days</code> 控制在线会话历史；<code>tsdb.retention_days</code> 控制时序数据；它们不能互相替代。</li><li>用户主题的 <code>window.*</code> 变量不是 Dashboard YAML 字段，放在 <code>custom_code</code> 中，由所选主题解释。</li></ul><h2 id="配置之外的边界" tabindex="-1">配置之外的边界 <a class="header-anchor" href="#配置之外的边界" aria-label="Permalink to &quot;配置之外的边界&quot;">​</a></h2><p>Agent 能执行的操作还取决于进程操作系统权限；Dashboard 的用户权限、PAT scope 和服务器白名单仍然生效。关闭强制登录不等于公开所有服务器，也不等于取消管理接口鉴权。详见<a href="/guide/security.html">安全与隐私</a>。</p>',10)])])}const f=e(r,[["render",n]]);export{u as __pageData,f as default};
